CREATE TABLE IF NOT EXISTS public.categories (
    id text PRIMARY KEY,
    title text NOT NULL,
    icon text NOT NULL,
    color text NOT NULL DEFAULT 'emerald',
    sort_order int NOT NULL DEFAULT 0,
    created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.apps (
    id text PRIMARY KEY,
    category_id text REFERENCES public.categories(id) ON DELETE SET NULL,
    name text NOT NULL,
    "desc" text NOT NULL,
    icon text NOT NULL,
    url text NOT NULL,
    action text NOT NULL DEFAULT 'Uygulamayı Aç',
    status text NOT NULL DEFAULT 'active',
    sort_order int NOT NULL DEFAULT 0,
    created_at timestamptz DEFAULT now(),
    updated_at timestamptz DEFAULT now()
);

ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.apps ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'categories_select_all') THEN
        CREATE POLICY categories_select_all ON public.categories FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'apps_select_all') THEN
        CREATE POLICY apps_select_all ON public.apps FOR SELECT USING (true);
    END IF;
END
$$;

